{"name": "submit_world_c_job", "arguments": {"title": "Gray-Scott morphospace anisotropy: 5pt vs 9pt Laplacian stencil", "script_content": "import numpy as np, json, time, csv
from numba import njit
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt

@njit
def lap5(u,o):
    L=u.shape[0]
    for y in range(L):
        for x in range(L):
            o[y,x]=u[(y+1)%L,x]+u[(y-1)%L,x]+u[y,(x+1)%L]+u[y,(x-1)%L]-4.0*u[y,x]

@njit
def lap9(u,o):
    L=u.shape[0]
    for y in range(L):
        for x in range(L):
            orth=u[(y+1)%L,x]+u[(y-1)%L,x]+u[y,(x+1)%L]+u[y,(x-1)%L]
            diag=u[(y+1)%L,(x+1)%L]+u[(y+1)%L,(x-1)%L]+u[(y-1)%L,(x+1)%L]+u[(y-1)%L,(x-1)%L]
            o[y,x]=(4.0*orth+1.0*diag-20.0*u[y,x])/6.0

@njit
def step(u,v,t1,t2,dt,F,k,Du,Dv,kind):
    L=u.shape[0]
    if kind==0: lap5(u,t1); lap5(v,t2)
    else: lap9(u,t1); lap9(v,t2)
    for y in range(L):
        for x in range(L):
            uu=u[y,x]; vv=v[y,x]; uv2=uu*vv*vv
            nu=uu+dt*(F*(1.0-uu)-uv2+Du*t1[y,x]); nv=vv+dt*(uv2-(F+k)*vv+Dv*t2[y,x])
            u[y,x]=0.0 if nu<0 else (1.0 if nu>1 else nu); v[y,x]=0.0 if nv<0 else (1.0 if nv>1 else nv)

def seed(L,r,sn):
    rng=np.random.default_rng(sn); u=np.ones((L,L)); v=np.zeros((L,L)); c=L//2
    u[c-r:c+r,c-r:c+r]=0.5; v[c-r:c+r,c-r:c+r]=0.25
    u+=rng.uniform(-0.05,0.05,size=(L,L)); v+=rng.uniform(-0.05,0.05,size=(L,L))
    return np.clip(u,0,1),np.clip(v,0,1)

def anisotropy(v):
    if float((v>0.2).mean())<0.05: return float('nan')
    F=np.fft.fft2(v-np.mean(v)); P=np.abs(F)**2
    ny,nx=P.shape
    ky=np.fft.fftfreq(ny).reshape(-1,1); kx=np.fft.fftfreq(nx).reshape(1,-1)
    ang=np.angle(kx+1j*ky); r2=kx*kx+ky*ky
    mask=r2>0; bins=np.floor((ang[mask]+np.pi)/(2*np.pi)*36).astype(int)%36
    sums=np.bincount(bins,P[mask],minlength=36).astype(float); sums[sums==0]=1e-12
    return float(sums.max()/sums.min())

L=128; dt=1.0; steps=10000; Du=0.16; Dv=0.08; r=10; sn=42
Fs=np.linspace(0.022,0.050,6); Ks=np.linspace(0.045,0.065,6)
rows=[]
cov5map=np.zeros((6,6)); aniso5map=np.zeros((6,6)); ratio_map=np.zeros((6,6))
for i,F in enumerate(Fs):
    for j,k in enumerate(Ks):
        u0,v0=seed(L,r,sn)
        u,v=u0.copy(),v0.copy(); t1=np.empty((L,L)); t2=np.empty((L,L))
        for _ in range(steps): step(u,v,t1,t2,dt,F,k,Du,Dv,0)
        cov5=float((v>0.2).mean()); std5=float(v.std()); aniso5=anisotropy(v)
        u,v=u0.copy(),v0.copy()
        for _ in range(steps): step(u,v,t1,t2,dt,F,k,Du,Dv,1)
        cov9=float((v>0.2).mean()); std9=float(v.std()); aniso9=anisotropy(v)
        ratio=aniso5/aniso9 if (aniso5==aniso5 and aniso9>0) else float('nan')
        rows.append(dict(F=round(float(F),4),k=round(float(k),4),cov5=cov5,std5=std5,aniso5=aniso5,cov9=cov9,std9=std9,aniso9=aniso9,ratio=ratio))
        cov5map[i,j]=cov5; aniso5map[i,j]=aniso5 if aniso5==aniso5 else 0; ratio_map[i,j]=ratio if ratio==ratio else 0
        print('F=%.3f k=%.3f cov5=%.3f aniso5=%.2f cov9=%.3f aniso9=%.2f ratio=%.2f'%(F,k,cov5,aniso5,cov9,aniso9,ratio))

with open('gs_morpho_sweep.csv','w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['F','k','cov5','std5','aniso5','cov9','std9','aniso9','ratio']); w.writeheader()
    for r in rows: w.writerow(r)

fig,axes=plt.subplots(1,3,figsize=(15,4.5))
for ax,mat,title in [(axes[0],cov5map,'Pattern coverage (5pt)'),(axes[1],aniso5map,'5pt angular anisotropy'),(axes[2],ratio_map,'Anisotropy ratio 5pt/9pt')]:
    im=ax.imshow(mat,origin='lower',aspect='auto',extent=[Ks.min(),Ks.max(),Fs.min(),Fs.max()]); plt.colorbar(im,ax=ax); ax.set_xlabel('k'); ax.set_ylabel('F'); ax.set_title(title)
plt.tight_layout(); plt.savefig('gs_morpho_sweep.png',dpi=110); plt.close()
print('SWEEP DONE. rows=%d'%len(rows))
", "timeout_seconds": 1800, "stage_name": "gs_morpho_sweep"}}
