    ang=np.angle(kx+1j*ky); r2=kx*kx+ky*ky; mask=r2>0
    bins=np.floor((ang[mask]+np.pi)/(2*np.pi)*36).astype(int)%36
    s=np.bincount(bins,P[mask],minlength=36).astype(float); s[s==0]=1e-12
    return float(s.max()/s.min())

