        axes[j,sn].imshow(panel[init][sn],cmap='magma'); axes[j,sn].axis('off')
        axes[j,sn].set_title('%s s%d'%(init,sn),fontsize=8)
axes[0,0].set_ylabel('localized seed',fontsize=9); axes[1,0].set_ylabel('homog. nucleation',fontsize=9)
