{"script_content": "# Job v6: Discovery-029 H3 (finite-size) + H4 (time-resolved growth of tail excess)
# 1D focusing NLS, Strang split-step (validated, mass dev ~1e-11).
# H3: N=2048, L in {25,50,100,200}, eps=0.1, 8 seeds; frames t in [40,100] every 1.0.
#     -> tail ratio P_obs/P_Rayleigh at s=4,6,8,10 + gamma_eff vs L.
# H4: N=2048, L=100, eps=0.1, 8 seeds; frames every 0.5 tu from t=0 to 100;
#     -> tail counts at s=4,6,8 binned into log-spaced time windows => ratio(t).
import os, time, json, sys
import numpy as np
import multiprocessing as mp

T0 = time.time()
GUARD = float(os.environ.get('IT_GUARD', '2600'))
CH = int(os.environ.get('IT_CHUNK', '8'))

def say(m):
    print('[H34 ' + str(round(time.time() - T0, 1)) + 's] ' + str(m)); sys.stdout.flush()

RAY = {4: np.exp(-4.0) * (1 + 4), 6: np.exp(-6.0) * (1 + 6),
       8: np.exp(-8.0) * (1 + 8), 10: np.exp(-10.0) * (1 + 10)}
THRS = [4.0, 6.0, 8.0, 10.0]

def run_real(args):
    (seed, N, L, dt, T, eps, t0frame, dtframe, tstop_frame, logbins) = args
    try:
        dx = L / N
        k = 2.0 * np.pi * np.fft.fftfreq(N, d=dx)
        lin_half = np.exp(-0.5j * (k * k) * dt)
        nsteps = int(round(T / dt))
        rng = np.random.default_rng(seed)
        psi = np.ones(N, dtype=complex)
        psi += eps * (rng.standard_normal(N) + 1j * rng.standard_normal(N)) / np.sqrt(2)
        if abs(psi.real.mean()) > 1e-9:
            psi += (1.0 - psi.real.mean())
        I0 = (psi.real ** 2 + psi.imag ** 2).mean()
        bins = np.arange(0, 20.0001, 0.25)
        hist = np.zeros(len(bins) - 1)
        cnt = {str(t): 0 for t in THRS}
        nsamp = 0
        massdev = 0.0
        logcnt = {}
        for lb in logbins:
            logcnt[lb[0]] = {str(t): [0, 0] for t in THRS}
        tnext = t0frame
        nframes = 0
        for n in range(1, nsteps + 1):
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            psi *= np.exp(2j * dt * (psi.real ** 2 + psi.imag ** 2))
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            t = n * dt
            if t >= tnext - 1e-12 and t <= tstop_frame + 1e-12:
                I = psi.real ** 2 + psi.imag ** 2
                m1 = I.mean()
                massdev = max(massdev, abs(m1 - I0))
                if t >= 40.0:
                    h, _ = np.histogram(I, bins=bins)
                    hist += h
                    nsamp += N
                    for ts in THRS:
                        cnt[str(ts)] += int((I >= ts * m1).sum())
                # log-time binning for H4
                if logbins:
                    import bisect
                    for lb in logbins:
                        if lb[0] <= t < lb[1]:
                            for ts in THRS:
                                logcnt[lb[0]][str(ts)][0] += int((I >= ts * m1).sum())
                                logcnt[lb[0]][str(ts)][1] += N
                            break
                nframes += 1
                tnext += dtframe
        out = {'ok': True, 'seed': seed, 'hist': hist.tolist(), 'nsamp': nsamp,
               'cnt': cnt, 'massdev': massdev, 'nframes': nframes}
        if logbins:
            out['logcnt'] = {str(kk): v for kk, v in logcnt.items()}
        return out
    except Exception as e:
        return {'ok': False, 'seed': seed, 'err': repr(e)}

def aggr(res, need_hist=True):
    ok = [r for r in res if r.get('ok')]
    if not ok:
        return None
    out = {'n_ok': len(ok), 'massdev': float(np.mean([r['massdev'] for r in ok]))}
    if need_hist:
        bins = np.arange(0, 20.0001, 0.25)
        hist = np.sum([np.array(r['hist']) for r in ok], axis=0)
        c = 0.5 * (bins[:-1] + bins[1:])
        bw = np.diff(bins)
        pdf = hist / hist.sum() / bw
        sel = (c >= 4.0) & (c <= 12.0) & (hist >= 40)
        out['gamma_eff'] = float(-np.polyfit(c[sel], np.log(pdf[sel]), 1)[0]) if sel.sum() >= 5 else None
        out['tails'] = {}
        for ts in THRS:
            P = sum(r['cnt'][str(ts)] for r in ok) / sum(r['nsamp'] for r in ok)
            out['tails'][str(int(ts))] = {'P': float(P), 'ratio': float(P / RAY[int(ts)])}
    # H4 log-time aggregation
    if any('logcnt' in r for r in ok):
        lg = {}
        for key in sorted({kk for r in ok for kk in r.get('logcnt', {})}, key=float):
            num = {ts: 0 for ts in THRS}
            den = 0
            for r in ok:
                if key in r.get('logcnt', {}):
                    for ts in THRS:
                        num[ts] += r['logcnt'][key][ts][0]
                    den += r['logcnt'][key]['4.0'][1]
            if den > 0:
                lg[key] = {('ratio%d' % int(ts)): float((num[ts] / den) / RAY[int(ts)])
                           for ts in THRS}
                lg[key]['t_mid'] = float(np.sqrt(float(key) * float(key) * 4))  # geometric midpoint approx
        out['logtime'] = lg
    return out

def run_cfg(name, jobs, pool):
    res = []
    i = 0
    while i < len(jobs):
        chunk = jobs[i:i + CH]
        got = []
        try:
            if pool is not None:
                ars = [pool.apply_async(run_real, (j,)) for j in chunk]
                got = [a.get(timeout=1200) for a in ars]
            else:
                for j in chunk:
                    if time.time() - T0 > GUARD:
                        break
                    got.append(run_real(j))
        except Exception as e:
            say('chunk fail ' + name + ': ' + repr(e)[:120])
            if pool is not None:
                pool.terminate(); pool = None
                say('-> serial fallback')
            got = []
            for j in chunk:
                if time.time() - T0 > GUARD:
                    break
                got.append(run_real(j))
        res.extend([g for g in got if g.get('ok')])
        i += CH
        say(name + ' chunk: ok=' + str(len(res)) + '/' + str(len(jobs)))
        json.dump({'name': name, 'n_ok': len(res), 'guard_hit': time.time() - T0 > GUARD},
                  open('h34_progress_' + name.replace(' ', '_') + '.json', 'w'))
    ag = aggr(res, need_hist=True)
    out = {'name': name, 'n_ok': ag['n_ok'] if ag else 0, 'wall': round(time.time() - T0, 1)}
    if ag:
        for kk in ('gamma_eff', 'tails', 'logtime', 'massdev'):
            if kk in ag:
                out[kk] = ag[kk]
    json.dump(out, open('h34_result_' + name.replace(' ', '_') + '.json', 'w'))
    say('saved h34_result_' + name.replace(' ', '_') + '.json n_ok=' + str(out['n_ok']))
    return out, pool

def main():
    say('v6 start guard=' + str(GUARD) + ' cpus=' + str(mp.cpu_count()))
    N, dt, T = 2048, 1e-3, 100.0
    nreal = int(os.environ.get('IT_NREAL', '8'))
    jobs_all = []
    names = []
    # H3: finite-size (vary L at fixed N)
    for L in (25.0, 50.0, 100.0, 200.0):
        nm = 'H3_L' + str(int(L))
        names.append(nm)
        jobs_all.append((nm, [(7700 + int(L) + i * 10, N, L, dt, T, 0.1, 40.0, 1.0, 100.0, None)
                              for i in range(nreal)]))
    # H4: time-resolved
    lb = []
    t = 0.5
    while t <= 100.0:
        lb.append((t, min(t * 2.0, 101.0)))
        t *= 2.0
    nm = 'H4_time'
    names.append(nm)
    jobs_all.append((nm, [(8800 + i, N, 100.0, dt, T, 0.1, 0.0, 0.5, 100.0, lb)
                          for i in range(nreal)]))
    pool = None
    try:
        nw = min(8, mp.cpu_count())
        pool = mp.Pool(nw)
        say('pool ' + str(nw))
    except Exception as e:
        say('pool fail ' + repr(e)[:80])
    results = {}
    for nm, jobs in jobs_all:
        r, pool = run_cfg(nm, jobs, pool)
        results[nm] = r
        if time.time() - T0 > GUARD - 300:
            say('guard margin low -> stop series')
            break
    json.dump(results, open('h34_all_results.json', 'w'))
    say('ALL DONE')
    try:
        if pool is not None:
            pool.close(); pool.join()
    except Exception:
        pass

