        out['L%g'%L]=summary
    json.dump(out,open('c35_summary.json','w'),indent=1); say('DONE')", "timeout_seconds": 7200, "title": "C35: mechanism test — fixed dx, L in {50,100,200}: is the tail excess set by structure density per unit length?"}}
