def detect_critical_point(
    param_values: np.ndarray,
    susceptibility: np.ndarray
) -> Dict[str, float]:
    """
    Locates the critical point K_c where susceptibility reaches its global maximum.
    Uses parabolic interpolation around the peak for sub-grid resolution.
    """
    if len(param_values) != len(susceptibility):
        raise ValueError("Parameter values and susceptibility arrays must have equal length")

    peak_idx = int(np.argmax(susceptibility))

    # Sub-grid refinement via parabolic interpolation
    if 0 < peak_idx < len(param_values) - 1:
        x0, x1, x2 = param_values[peak_idx - 1], param_values[peak_idx], param_values[peak_idx + 1]
        y0, y1, y2 = susceptibility[peak_idx - 1], susceptibility[peak_idx], susceptibility[peak_idx + 1]

        # Vertex of parabola through (x0, y0), (x1, y1), (x2, y2)
        denom = (x0 - x1) * (x0 - x2) * (x1 - x2)
        if abs(denom) > 1e-14:
            a = (x2 * (y1 - y0) + x1 * (y0 - y2) + x0 * (y2 - y1)) / denom
            b = (x2**2 * (y0 - y1) + x1**2 * (y2 - y0) + x0**2 * (y1 - y2)) / denom
            if abs(a) > 1e-14:
                k_crit = -b / (2.0 * a)
            else:
                k_crit = x1
        else:
            k_crit = x1
    else:
        k_crit = param_values[peak_idx]

    return {
        "k_critical": float(k_crit),
        "peak_susceptibility": float(susceptibility[peak_idx]),
        "peak_index": float(peak_idx)
    }

def __init__(
        self,
        n_oscillators: int = 100,
        natural_frequencies: Optional[np.ndarray] = None,
        coupling_matrix: Optional[np.ndarray] = None,
        freq_distribution: str = "cauchy",
        freq_scale: float = 1.0,
        seed: Optional[int] = None
    ):
        self.N = n_oscillators
        self.rng = np.random.default_rng(seed)

        if natural_frequencies is not None:
            if len(natural_frequencies) != self.N:
                raise ValueError(f"Frequencies length ({len(natural_frequencies)}) != N ({self.N})")
            self.omega = np.asarray(natural_frequencies, dtype=np.float64)
        else:
            if freq_distribution == "cauchy":
                # Standard Cauchy distribution with scale gamma
                u = self.rng.uniform(0.01, 0.99, size=self.N)
                self.omega = freq_scale * np.tan(np.pi * (u - 0.5))
            elif freq_distribution == "gaussian":
                self.omega = self.rng.normal(0.0, freq_scale, size=self.N)
            elif freq_distribution == "uniform":
                self.omega = self.rng.uniform(-freq_scale, freq_scale, size=self.N)
            else:
                raise ValueError(f"Unknown frequency distribution: {freq_distribution}")

        self.A = coupling_matrix.astype(np.float64) if coupling_matrix is not None else None
        self.theta = self.rng.uniform(-np.pi, np.pi, size=self.N).astype(np.float64)

