    ks=[]; als=[]
    for s in SEEDS:
        d=res[name+"_seed%d"%s]; K=np.array(d["K"]); R=np.array(d["R"])
        kc=kcrit(K,R); als.append(fit_alpha(K,R,kc)[0]); ks.append(kc)
    out["topologies"][name]=dict(Kc_mean=float(np.nanmean(ks)),Kc_std=float(np.nanstd(ks)),
