{"name": "submit_world_c_job", "arguments": {"script_content": "# Job v7: Discovery-029 H3 (finite-size) + H4 (time-resolved growth) -- bugfixes
# Fixes vs v6: (1) logbins=None handled (no logcnt code path for H3);
#              (2) logcnt keys stored as str at creation, looked up consistently as str.
# H3: N=2048, L in {25,50,100,200}, eps=0.1, 8 seeds, frames t in [40,100] every 1.0.
# H4: N=2048, L=100, eps=0.1, 8 seeds, frames every 0.5 tu from t=0..100, log2 time bins.
import os, time, json, sys
import numpy as np
import multiprocessing as mp

T0 = time.time()
GUARD = float(os.environ.get('IT_GUARD', '2600'))
CH = int(os.environ.get('IT_CHUNK', '8'))

def say(m):
    print('[H34 ' + str(round(time.time() - T0, 1)) + 's] ' + str(m)); sys.stdout.flush()

RAY = {4: np.exp(-4.0) * (1 + 4), 6: np.exp(-6.0) * (1 + 6),
       8: np.exp(-8.0) * (1 + 8), 10: np.exp(-10.0) * (1 + 10)}
THRS = [4.0, 6.0, 8.0, 10.0]
TSKEY = {4.0: '4', 6.0: '6', 8.0: '8', 10.0: '10'}

def run_real(args):
    (seed, N, L, dt, T, eps, t0frame, dtframe, tstop_frame, logbins) = args
    try:
        dx = L / N
        k = 2.0 * np.pi * np.fft.fftfreq(N, d=dx)
        lin_half = np.exp(-0.5j * (k * k) * dt)
        nsteps = int(round(T / dt))
        rng = np.random.default_rng(seed)
        psi = np.ones(N, dtype=complex)
        psi += eps * (rng.standard_normal(N) + 1j * rng.standard_normal(N)) / np.sqrt(2)
        if abs(psi.real.mean()) > 1e-9:
            psi += (1.0 - psi.real.mean())
        I0 = (psi.real ** 2 + psi.imag ** 2).mean()
        bins = np.arange(0, 20.0001, 0.25)
        hist = np.zeros(len(bins) - 1)
        cnt = {'4': 0, '6': 0, '8': 0, '10': 0}
        nsamp = 0
        massdev = 0.0
        logcnt = None
        if logbins:
            logcnt = {}
            for lb in logbins:
                logcnt[str(lb[0])] = {'4': [0, 0], '6': [0, 0], '8': [0, 0], '10': [0, 0]}
        tnext = t0frame
        nframes = 0
        for n in range(1, nsteps + 1):
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            psi *= np.exp(2j * dt * (psi.real ** 2 + psi.imag ** 2))
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            t = n * dt
            if t >= tnext - 1e-12 and t <= tstop_frame + 1e-12:
                I = psi.real ** 2 + psi.imag ** 2
                m1 = I.mean()
                massdev = max(massdev, abs(m1 - I0))
                if t >= 40.0:
                    h, _ = np.histogram(I, bins=bins)
                    hist += h
                    nsamp += N
                    for ts in THRS:
                        cnt[TSKEY[ts]] += int((I >= ts * m1).sum())
                if logcnt is not None:
                    for lb in logbins:
                        if lb[0] <= t < lb[1]:
                            bucket = logcnt[str(lb[0])]
                            for ts in THRS:
                                kk = TSKEY[ts]
                                bucket[kk][0] += int((I >= ts * m1).sum())
                                bucket[kk][1] += N
                            break
                nframes += 1
                tnext += dtframe
        out = {'ok': True, 'seed': seed, 'hist': hist.tolist(), 'nsamp': nsamp,
               'cnt': cnt, 'massdev': massdev, 'nframes': nframes}
        if logcnt is not None:
            out['logcnt'] = logcnt
        return out
    except Exception as e:
        import traceback
        return {'ok': False, 'seed': seed, 'err': repr(e) + '|' + traceback.format_exc()[-200:]}

def aggr(res, need_hist=True):
    ok = [r for r in res if r.get('ok')]
    if not ok:
        return None
    out = {'n_ok': len(ok), 'massdev': float(np.mean([r['massdev'] for r in ok])),
           'errs': [r.get('err', '')[:100] for r in res if not r.get('ok')]}
    if need_hist:
        bins = np.arange(0, 20.0001, 0.25)
        hist = np.sum([np.array(r['hist']) for r in ok], axis=0)
        c = 0.5 * (bins[:-1] + bins[1:])
        bw = np.diff(bins)
        pdf = hist / hist.sum() / bw
        sel = (c >= 4.0) & (c <= 12.0) & (hist >= 40)
        out['gamma_eff'] = float(-np.polyfit(c[sel], np.log(pdf[sel]), 1)[0]) if sel.sum() >= 5 else None
        out['tails'] = {}
        for ts in THRS:
            P = sum(r['cnt'][TSKEY[ts]] for r in ok) / sum(r['nsamp'] for r in ok)
            out['tails'][str(int(ts))] = {'P': float(P), 'ratio': float(P / RAY[int(ts)])}
    if any('logcnt' in r for r in ok):
        lg = {}
        keys = sorted({kk for r in ok for kk in r.get('logcnt', {})}, key=float)
        for key in keys:
            num = {'4': 0, '6': 0, '8': 0, '10': 0}
            den = 0
            for r in ok:
                b = r.get('logcnt', {}).get(key)
                if b:
                    for ts in THRS:
                        kk = TSKEY[ts]
                        num[kk] += b[kk][0]
                    den += b['4'][1]
            if den > 0:
                ent = {'t_lo': float(key), 't_hi': float(key) * 2.0}
                for ts in THRS:
                    kk = TSKEY[ts]
                    ent['ratio' + kk] = float((num[kk] / den) / RAY[int(ts)])
                lg[key] = ent
        out['logtime'] = lg
    return out

def run_cfg(name, jobs, pool, need_hist=True):
    res = []
    i = 0
    while i < len(jobs):
        chunk = jobs[i:i + CH]
        got = []
        try:
            if pool is not None:
                ars = [pool.apply_async(run_real, (j,)) for j in chunk]
                got = [a.get(timeout=1200) for a in ars]
            else:
                for j in chunk:
                    if time.time() - T0 > GUARD:
                        break
                    got.append(run_real(j))
        except Exception as e:
            say('chunk fail ' + name + ': ' + repr(e)[:120])
            try:
                if pool is not None:
                    pool.terminate(); pool = None
            except Exception:
                pool = None
            say('-> serial fallback')
            got = []
            for j in chunk:
                if time.time() - T0 > GUARD:
                    break
                got.append(run_real(j))
        bad = [g for g in got if not g.get('ok')]
        if bad:
            say(name + ' bad=' + str(len(bad)) + ' err0=' + (bad[0].get('err', '')[:140]))
        res.extend([g for g in got if g.get('ok')])
        i += CH
        say(name + ' chunk: ok=' + str(len(res)) + '/' + str(len(jobs)))
        json.dump({'name': name, 'n_ok': len(res), 'guard_hit': time.time() - T0 > GUARD},
                  open('h34b_progress_' + name.replace(' ', '_') + '.json', 'w'))
    ag = aggr(res, need_hist=need_hist)
    out = {'name': name, 'n_ok': ag['n_ok'] if ag else 0, 'wall': round(time.time() - T0, 1)}
    if ag:
        for kk in ('gamma_eff', 'tails', 'logtime', 'massdev', 'errs'):
            if kk in ag:
                out[kk] = ag[kk]
    json.dump(out, open('h34b_result_' + name.replace(' ', '_') + '.json', 'w'))
    say('saved h34b_result_' + name.replace(' ', '_') + '.json n_ok=' + str(out['n_ok']))
    return out, pool

def main():
    say('v7 start guard=' + str(GUARD) + ' cpus=' + str(mp.cpu_count()))
    N, dt, T = 2048, 1e-3, 100.0
    nreal = int(os.environ.get('IT_NREAL', '8'))
    jobs_all = []
    for L in (25.0, 50.0, 100.0, 200.0):
        nm = 'H3_L' + str(int(L))
        jobs_all.append((nm, [(7700 + int(L) + i * 10, N, L, dt, T, 0.1, 40.0, 1.0, 100.0, None)
                              for i in range(nreal)]))
    lb = []
    t = 0.5
    while t <= 100.0:
        lb.append((t, min(t * 2.0, 101.0)))
        t *= 2.0
    nm = 'H4_time'
    jobs_all.append((nm, [(8800 + i, N, 100.0, dt, T, 0.1, 0.0, 0.5, 100.0, lb)
                          for i in range(nreal)]))
    pool = None
    try:
        nw = min(8, mp.cpu_count())
        pool = mp.Pool(nw)
        say('pool ' + str(nw))
    except Exception as e:
        say('pool fail ' + repr(e)[:80])
    results = {}
    for nm, jobs in jobs_all:
        r, pool = run_cfg(nm, jobs, pool)
        results[nm] = r
        json.dump(results, open('h34b_all_results.json', 'w'))
        if time.time() - T0 > GUARD - 300:
            say('guard margin low -> stop series')
            break
    json.dump(results, open('h34b_all_results.json', 'w'))
    say('ALL DONE')
    try:
        if pool is not None:
            pool.close(); pool.join()
    except Exception:
        pass

if __name__ == '__main__':
    main()
