RAY = {4: np.exp(-4.0) * (1 + 4), 6: np.exp(-6.0) * (1 + 6),
       8: np.exp(-8.0) * (1 + 8), 10: np.exp(-10.0) * (1 + 10)}
THRS = [4.0, 6.0, 8.0, 10.0]
TSKEY = {4.0: '4', 6.0: '6', 8.0: '8', 10.0: '10'}

def run_real(args):
    (seed, N, L, dt, T, eps) = args
    try:
        dx = L / N
        k = 2.0 * np.pi * np.fft.fftfreq(N, d=dx)
        lin_half = np.exp(-0.5j * (k * k) * dt)
        nsteps = int(round(T / dt))
        rng = np.random.default_rng(seed)
        psi = np.ones(N, dtype=complex)
        psi += eps * (rng.standard_normal(N) + 1j * rng.standard_normal(N)) / np.sqrt(2)
        if abs(psi.real.mean()) > 1e-9:
            psi += (1.0 - psi.real.mean())
        I0 = (psi.real ** 2 + psi.imag ** 2).mean()
        cnt = {'4': 0, '6': 0, '8': 0, '10': 0}
        nsamp = 0
        massdev = 0.0
        Imax_track = 0.0
        tnext = 40.0
        for n in range(1, nsteps + 1):
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            psi *= np.exp(2j * dt * (psi.real ** 2 + psi.imag ** 2))
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            t = n * dt
            if t >= tnext - 1e-12 and t <= 100.0 + 1e-12:
                I = psi.real ** 2 + psi.imag ** 2
                m1 = I.mean()
                massdev = max(massdev, abs(m1 - I0))
                Imax_track = max(Imax_track, I.max())
                nsamp += N
                for ts in THRS:
                    cnt[TSKEY[ts]] += int((I >= ts * m1).sum())
                tnext += 1.0
        out = {'ok': True, 'seed': seed, 'nsamp': nsamp, 'cnt': cnt,
               'massdev': massdev, 'Imax': float(Imax_track)}
        return out
    except Exception as e:
        return {'ok': False, 'seed': seed, 'err': repr(e)}

def aggr(res):
    ok = [r for r in res if r.get('ok')]
    if not ok:
        return {'n_ok': 0}
    per_seed = []
    for r in ok:
        ent = {'seed': r['seed'], 'nsamp': r['nsamp'], 'Imax': r['Imax']}
        for ts in THRS:
            kk = TSKEY[ts]
            ent['ratio' + kk] = float((r['cnt'][kk] / r['nsamp']) / RAY[int(ts)])
        per_seed.append(ent)
