        var_stats[kk] = {'mean': float(v.mean()), 'std': float(v.std(ddof=1)),
                         'min': float(v.min()), 'max': float(v.max()),
                         'cv': float(v.std(ddof=1) / max(v.mean(), 1e-12))}
    return {'n_ok': len(ok), 'pooled': pooled, 'var_stats': var_stats,
            'per_seed': per_seed,
            'massdev': float(np.mean([r['massdev'] for r in ok]))}

def main():
    say('v8 start guard=' + str(GUARD) + ' cpus=' + str(mp.cpu_count()))
    N, dt, T, eps = 2048, 1e-3, 100.0, 0.1
    nreal = int(os.environ.get('IT_NREAL', '32'))
    jobs_all = []
